 const h=NEWS_HUB[lang],groups=['news','announcements','updates'];
 if(newsArticle!==null){const item=h.stories[newsArticle],article=el('article','news-article');const back=el('button','back',h.back);back.onclick=()=>{newsArticle=null;renderExtra()};article.append(back,el('span','news-story-meta',item[1]),el('h1','',item[2]),el('p','',item[3]),el('div','news-hub-note',h.examples),el('p','',item[4]));v.append(article);return}
