 const section=el('section','news-hub-section');const head=el('div','news-hub-section-head');const headingWrap=el('div');headingWrap.append(el('h2','',heading),el('p','',desc));head.append(headingWrap);
 const entries=h.stories.map((item,i)=>({item,i})).filter(x=>x.item[0]===key);const isArchive=newsFocus===key;
