 const grid=el('div','news-hub-grid');visible.forEach(({item,i})=>{const b=el('button','news-story');b.type='button';b.append(el('span','news-story-meta',item[1]),el('strong','',item[2]),el('p','',item[3]),el('span','news-story-action',h.read));b.onclick=()=>{newsArticle=i;renderExtra();window.scrollTo(0,0)};grid.append(b)});
