function getCategory(tags){return tags.amenity==='library'?'library':tags.amenity==='fire_station'?'fire':tags.amenity==='police'?'police':'civic'}
function mapName(o){return o.tags['name:en']||o.tags.name||o.tags.operator||'Public service location'}
function mapLabel(o){return [o.tags['addr:housenumber'],o.tags['addr:street']].filter(Boolean).join(' ')||o.tags['addr:full']||''}
