 fact(es?'Responsable':'Ownership',projectOwnerText(p));fact(es?'Categoría':'Category',projTr().types[p.kind[2]]);fact(es?'Zona':'Area',(es?projectAreasEs:projectAreas)[p.areaIndex]);fact(es?'Estado':'Status',projTr()[p.status]);fact(es?'Avance':'Progress',p.percent+'%');fact(es?'Actualizado':'Last updated',p.updated);
 if(p.owner==='city')fact(es?'Costo estimado (demo)':'Estimated cost (demo)',new Intl.NumberFormat(es?'es-US':'en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(p.budget));
 facts.append(dl);if(p.owner==='external')facts.append(el('p','project-privacy-note',es?'Este proyecto no es financiado por la Ciudad. No se publica información de costos.':'This is not a City-funded project. Cost information is not displayed.'));
 layout.append(main,aside);dir.append(layout,el('p','project-note',projTr().note));window.scrollTo(0,0);
