const verifiedSantaFeServiceSources={"jobs":["How to apply for City jobs","View current City job openings in the employment portal and submit an application for a listed position. Human Resources can assist with application questions.","Human Resources · 505-955-6513 · HumanResources@santafenm.gov","/how-to-apply"],"business":["Business registration and licensing","Businesses operating within Santa Fe city limits need a City business license. Register the business and obtain New Mexico gross receipts tax documentation, create an account in the City self-service portal, select the license category, complete the application, and follow the inspection and payment instructions.","Business Licensing · bizlicensing@santafenm.gov","/land-use/doing-business-with-the-city"],"license_renewal":["Renew a business license","Existing license holders can create or sign into a business profile and submit a renewal in the Citizen Self-Service portal. The City reviews the renewal and sends invoicing or requests additional information.","Business Licensing · bizlicensing@santafenm.gov","/land-use/doing-business-with-the-city/business-license-renewal"],"planning":["Planning and zoning review","The Current Planning Division reviews residential and commercial development applications against the Land Development Code and adopted City plans. Some applications require public hearings. Contact the zoning or permit counter for requirements and appointments.","Land Use · zoningcounter@santafenm.gov · permitcounter@santafenm.gov","/land-use/current-planning"],"parking":["Parking services","Find downtown garages and lots, parking meters, ADA accommodations, parking permits, citations, and special event parking. The Parking Division is located at 737 Agua Fria Street.","Parking Division · 505-955-6581 (option 1) · parking@santafenm.gov","/public-works/parking"],"parking_permit":["Apply for a parking permit","Review City parking permit policies and the application for garage, lot, or other eligible parking permits. Residential permit requirements vary by designated neighborhood.","Parking Division · 505-955-6581 (option 1)","/public-works/parking/application-for-parking-permit-online-form"],"parking_ticket":["Pay or dispute a parking citation","Pay a parking citation or request administrative review within 15 calendar days of issuance. After 15 days, the initial citation amount may double. Have your citation and license plate information available.","Parking Division · 505-955-6581 (option 1) · parking@santafenm.gov","/public-works/parking/parking-citations"],"utilities":["Utility customer service and billing","The City handles billing for water, refuse, sewer, and stormwater services. Find online bill payment, start/stop service, account transfers, forms, and water-usage tools.","Utility Customer Service · 505-955-4333 · utilitycustomerservice@santafenm.gov","/public-utilities/customer-service-and-utility-billing"],"water_start":["Start, stop, or transfer utility service","The City publishes separate forms and documentation for owners and tenants. Incomplete or unsigned applications cannot be processed. Review the required documents before submitting by email, mail, or the office drop box.","Utility Customer Service · 505-955-4333","/public-utilities/customer-service-and-utility-billing/startstop-service"],"water_forms":["Utility forms and applications","Access forms for owner account transfers, tenant utility services, low-income credits, vacancy credits, and water leak adjustments. The City requires complete and signed forms.","Utility Customer Service · 505-955-4333","/public-utilities/customer-service-and-utility-billing/forms"],"waste":["Trash and recycling collection","Find residential trash and recycling guidance, collection schedules, holiday changes, and the Environmental Services Division calendar. Collection schedules may shift around City-observed holidays.","Environmental Services · 505-955-2200 · ESD@santafenm.gov","/public-utilities/trash-and-recycling"],"waste_schedule":["Find your collection schedule","Review City residential collection days and the current holiday collection calendar. Check the official schedule for service changes.","Environmental Services · 505-955-2200","/public-utilities/trash-and-recycling/day-change"],"parks":["Parks and open space","Explore City parks, trails, open spaces, amenities, volunteer opportunities, and park or field reservations. The City manages more than 100 parks and approximately 170 miles of trails.","Parks & Open Space · 505-955-2106","/public-works/parks-and-open-space"],"parks_locator":["Find a park or recreation amenity","Use the City parks locator to browse neighborhood parks, trails, playgrounds, fields, picnic areas, and other amenities.","Parks & Open Space · 505-955-2106","/public-works/parks-and-open-space/parks-open-space-locator"],"recreation":["Recreation programs and facilities","Find information on City recreation complexes, pools, classes, programs, schedules, and recreation offerings. Check the facility page for current hours and any closures.","Recreation Division · Genoveva Chavez Community Center 505-955-4000","/community-services/recreation"],"seniors":["Senior services","The City provides programs for adults aged 60 and older, including senior centers, meals, activities, benefits counseling, and transportation. Meal and transportation participants must register.","Senior Services · 505-955-4721 · Transportation 505-955-4700","/community-services/division-of-senior-services"],"alerts":["Alert Santa Fe notifications","Alert Santa Fe is the City emergency notification system. Residents and visitors can sign up to receive emergency information by phone, text, or email and choose notification preferences.","Emergency Management · oem@santafenm.gov","/emergency-management/alertsantafe"],"report":["Report a concern or request City help","Constituent Services accepts questions and service requests about streets, potholes, graffiti, parks, recycling, permits, and other City matters. Staff review requests and route them to the appropriate team.","Constituent Services · 505-955-6949 · constituentservices@santafenm.gov","/city-clerk-community-engagement/cs"],"records":["Request public records (IPRA)","Under New Mexico’s Inspection of Public Records Act, you may request City public records online or by submitting a written request. Describe the records and provide your name, date, and contact information.","Public Records Office · 505-955-6643 · recordscustodian@santafenm.gov","/city-attorney/request-public-records"],"fire":["Fire prevention and permits","The Fire Marshal’s Office provides inspection requests, fire safety forms, and applications for open burning, fireworks, events, and other permits. Review permit requirements before submitting.","Fire Marshal’s Office · 505-955-3310 · sffd_fmo@santafenm.gov","/fire-department/fire-prevention-education/forms-applications"],"bus":["Santa Fe Trails transit","Find local bus routes, schedules, fare information, service notices, and transit programs through the City Transit Division.","Santa Fe Trails · City Transit Division","/public-works/transit"],"works":["Public Works services","The City Public Works Department manages streets, drainage, facilities, parking, parks and open space, and transit.","Public Works · 737 Agua Fria Street","/public-works"]};
function getSantaFeServiceSource(z){
 const n=z.en[0].toLowerCase();
 const rules=SERVICE_MATCH_RULES;
 for(const [key,pattern] of rules){if(new RegExp(pattern,'i').test(n))return {key,info:verifiedSantaFeServiceSources[key]};}
 return null;
}
const SERVICE_MATCH_RULES=[["parking_ticket","parking citation|pay or appeal a parking|pay a parking"],["parking_permit","parking permit|parking space closure|park on the street|park in a parking"],["license_renewal","renew.*business license"],["business","business licens|start a business|do business with the city|business registration"],["jobs","apply for a job|city job opportunit|city employment"],["water_start","start or stop water|start.stop water|start or stop.*service"],["water_forms","higher than expected bills|water leak adjustment"],["waste_schedule","trash or recycling schedule|holiday schedule updates|collection days"],["parking","parking|garage|metered"],["records","public records|request.*records"],["alerts","alert santa fe|sign up for.*alert|prepare for an emergency|emergency preparedness"],["seniors","older adult|senior services|senior program|senior citizen"],["parks_locator","facility search|find a park|enjoy greenways"],["parks","parks and open space|parks and recreation|picnic shelter|play pickleball|tennis|park reservation|athletics|greenway|adopt.a.street|stewarding public space"],["recreation","recreation|pool|summer camp|toddler program|youth program|teen program"],["fire","fire inspection|burn permit|smoke alarm|fire prevention"],["planning","zoning|building permit|trade permit|commercial site development|development review|remodel|build a|development neighborhood|permit information|land use|residential property|commercial property"],["bus","transit|bus|bicycle on the bus|ride the bus"],["waste","trash|recycling|waste|compost|litter|bulky|hazardous"],["utilities","water bill|water and utilit|utility bill|e.billing|water quality|water rates"],["report","report a problem|report a pothole|report graffiti|missed pickup|street light|solve a problem|community feedback|service request|storm drain|report.*concern"],["works","sidewalk|street maintenance|right of way"]];
function showServicePage(z){
 const v=document.getElementById('nav-view');if(!v||!z)return;const es=lang==='es';
 v.replaceChildren();const back=el('button','back',es?'← Todos los servicios':'← All services');back.onclick=()=>{selectedService=null;location.hash='services';drawNav()};
 const kicker=el('p','nav-kicker',es?'CIUDAD DE SANTA FE · SERVICIOS':'CITY OF SANTA FE · SERVICES');
 const title=el('h1','',z[lang][0]);const intro=el('p','sub',z[lang][1]);
 const matched=getSantaFeServiceSource(z);
 const verified=!!matched;
 const note=el('div','notice',verified?(es?'INFORMACIÓN BASADA EN EL SITIO OFICIAL DE SANTA FE. Este prototipo resume la información municipal; consulte la fuente para los requisitos y detalles vigentes.':'SANTA FE SOURCE-BASED INFORMATION. This prototype summarizes the City website; consult the official source for current requirements and details.'):(es?'SERVICIO DE DEMOSTRACIÓN. No se encontró una página municipal equivalente verificada para este tema; no se debe presentar como servicio disponible sin confirmación.':'PROTOTYPE SERVICE. A matching Santa Fe service page was not verified for this topic. Do not present it as an available City program without confirmation.'));
 const layout=el('div','service-page-layout'),main=el('div','service-page-content'),aside=el('aside','service-page-aside');
 function section(heading,body){const s=el('section','service-page-section');s.append(el('h2','',heading),el('p','',body));main.append(s);return s}
 if(verified){
   const info=matched.info;
   section(es?'Información del servicio':'Service information',info[1]);
   section(es?'Cómo comenzar':'Getting started',es?'Revise los pasos, formularios y requisitos vigentes en la página oficial enlazada a continuación.':'Review the current steps, forms, and requirements on the linked official City page.');
   section(es?'Contacto municipal':'City contact',info[2]);
   const source=section(es?'Fuente oficial':'Official source',es?'Información obtenida del sitio web oficial de la Ciudad de Santa Fe.':'Information drawn from the City of Santa Fe official website.');
   const link=el('a','service-official-source',es?'Consultar la página oficial ↗':'Read official service page ↗');link.href='https://santafenm.gov'+info[3];link.target='_blank';link.rel='noopener noreferrer';source.append(link);
 }else{
   section(es?'Acerca del tema':'About this topic',z[lang][1]);
   section(es?'Antes de comenzar':'Before you begin',es?'Esta categoría se incluyó para fines de diseño. Consulte el directorio oficial de servicios municipales para encontrar un programa equivalente, si existe.':'This category was included for design exploration. Check the official City services directory to determine whether a corresponding program exists.');
   const source=section(es?'Directorio oficial':'Official directory',es?'Explore los servicios publicados por la Ciudad.':'Explore services published by the City.');
   const link=el('a','service-official-source',es?'Ver servicios oficiales ↗':'View official City services ↗');link.href='https://santafenm.gov/city-services';link.target='_blank';link.rel='noopener noreferrer';source.append(link);
 }
 const help=el('div','service-help');help.append(el('p','service-origin',es?'AYUDA CON ESTE SERVICIO':'HELP WITH THIS SERVICE'),el('h2','',es?'¿Necesita ayuda?':'Need assistance?'),el('p','',es?'Encuentre al departamento correspondiente en el directorio municipal.':'Find the appropriate department in the City directory.'));
 const dept=el('button','service-page-action',es?'Explorar departamentos →':'Explore departments →');dept.onclick=()=>{selectedService=null;location.hash='departments';showNav(1)};help.append(dept);aside.append(help);layout.append(main,aside);
 v.append(back,kicker,title,intro,note,layout);window.scrollTo(0,0);
}
const oldDrawNav=drawNav;drawNav=function(){oldDrawNav();if(navPage===0){if(selectedService){const s=items.find(z=>z.id===selectedService);if(s){showServicePage(s);return}}
 const v=document.getElementById('nav-view');v.querySelector('.nav-demo-note')?.remove();
 const es=lang==='es';const heading=el('h2','service-directory-heading',es?'Directorio de servicios':'Services directory');
 const note=el('p','sub',es?'Directorio de servicios de Santa Fe. Las páginas nuevas son demostraciones y deben verificarse antes de publicarse.':'Santa Fe services directory. New internal service pages are prototypes and require verification before publication.');
 const tools=el('div','services-tools');const search=el('input');search.type='search';search.value=servicesSearch;search.placeholder=es?'Buscar en el directorio':'Search the directory';search.setAttribute('aria-label',search.placeholder);tools.append(search);
 const count=el('p','services-count');count.setAttribute('aria-live','polite');const letters=el('nav','service-letter-index');letters.setAttribute('aria-label',es?'Ir a una letra':'Jump to a letter');const directory=el('div','service-alpha-directory');
 function renderServices(){directory.replaceChildren();letters.replaceChildren();const q=servicesSearch.trim().toLocaleLowerCase();const matches=items.filter(z=>(z.url||z.source==='prototype')&&z.en[0].toLowerCase()!=='services directory'&&(!q||[...z.en,...z.es].join(' ').toLocaleLowerCase().includes(q))).sort((a,b)=>a[lang][0].localeCompare(b[lang][0],es?'es':'en',{sensitivity:'base'}));count.textContent=matches.length+' '+(es?'servicios en orden alfabético':'services in alphabetical order');
 const groups=new Map();matches.forEach(z=>{const name=z[lang][0].trim();const letter=name.charAt(0).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase();const key=/^[A-Z]$/.test(letter)?letter:'#';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(z)});
 for(const [letter,group] of groups){const anchor=el('a','service-letter-link',letter);anchor.href='#services-letter-'+letter;anchor.onclick=ev=>{ev.preventDefault();document.getElementById('services-letter-'+letter)?.scrollIntoView({behavior:'smooth',block:'start'})};letters.append(anchor);const section=el('section','service-letter-section');section.id='services-letter-'+letter;section.append(el('h3','service-letter-title',letter));const grid=el('div','official-services-grid');group.forEach(z=>{const a=el('a','official-service-link');const internal=z.source==='prototype';a.href=internal?'#service-'+z.id:z.url;if(!internal){a.target='_blank';a.rel='noopener noreferrer'}else{a.onclick=ev=>{ev.preventDefault();selectedService=z.id;location.hash='service-'+z.id;showServicePage(z)}}a.append(el('span','service-origin',internal?(getSantaFeServiceSource(z)?(es?'INFORMACIÓN MUNICIPAL':'CITY-SOURCED INFO'):(es?'SERVICIO · DEMO':'SERVICE · DEMO')):(es?'ENLACE OFICIAL':'OFFICIAL CITY LINK')),el('strong','',z[lang][0]),el('span','',z[lang][1]),el('span','official-service-arrow',internal?(es?'Ver servicio →':'View service →'):(es?'Visitar servicio ↗':'Visit service ↗')));grid.append(a)});section.append(grid);directory.append(section)}
 if(!matches.length)directory.append(el('p','',es?'No se encontraron servicios.':'No services found.'));
 }
 search.oninput=()=>{servicesSearch=search.value;renderServices()};v.append(heading,note,tools,count,letters,directory);renderServices();
 }if(navPage===2){const v=document.getElementById('nav-view');const cards=v.querySelector('.nav-cards');if(cards)cards.remove();const note=v.querySelector('.nav-demo-note');if(note)note.remove();const directory=el('section','project-board');directory.id='project-directory';v.append(directory);drawProjects()}};


