function drawContactTable(host){const es=lang==='es',box=el('section','contact-directory');host.append(box);const tools=el('div','contact-tools');const searchLabel=el('label','',es?'Buscar por nombre, cargo o departamento':'Search by name, title or department'),input=el('input');input.type='search';input.value=contactSearch;input.placeholder=es?'Buscar contactos...':'Search contacts...';input.oninput=()=>{contactSearch=input.value;contactPage=1;results()};searchLabel.append(input);const deptLabel=el('label','',es?'Departamento / división':'Department / division'),select=el('select');const opts=['all',...new Set(contactStaff.map(x=>x[2].split(' — ')[0]))].sort();opts.forEach(k=>{const o=el('option','',k==='all'?(es?'Todos los departamentos':'All departments'):k);o.value=k;select.append(o)});select.value=contactDept;select.onchange=()=>{contactDept=select.value;contactPage=1;results()};deptLabel.append(select);tools.append(searchLabel,deptLabel);box.append(tools);const content=el('div');box.append(content);function results(){content.replaceChildren();const q=contactSearch.toLowerCase().trim();const matches=contactStaff.filter(x=>(contactDept==='all'||x[2].startsWith(contactDept))&&(!q||x.join(' ').toLowerCase().includes(q))).sort((a,b)=>a[0].localeCompare(b[0]));content.append(el('p','project-note',matches.length+' '+(es?'contactos':'contacts')+' · '+(es?'Fuente: directorio oficial':'Source: official directory')));const wrap=el('div','contact-table-wrap'),table=el('table','contact-table'),thead=el('thead'),tr=el('tr');(es?['Nombre','Cargo','Departamento','Teléfono','Correo electrónico']:['Name','Title','Department','Phone','Email']).forEach(t=>{const th=el('th','',t);th.scope='col';tr.append(th)});thead.append(tr);table.append(thead);const tbody=el('tbody');matches.slice((contactPage-1)*10,contactPage*10).forEach(x=>{const row=el('tr');x.forEach((val,i)=>{const td=el('td');if(i===3){const a=contactLink(val,'tel:'+val,'');td.append(a)}else if(i===4){td.append(contactLink(val,'mailto:'+val,''))}else td.textContent=val;row.append(td)});tbody.append(row)});table.append(tbody);wrap.append(table);content.append(wrap);const total=Math.max(1,Math.ceil(matches.length/10)),pager=el('nav','contact-pagination');pager.setAttribute('aria-label',es?'Páginas del directorio':'Directory pages');const prev=el('button','',es?'Anterior':'Previous');prev.disabled=contactPage===1;prev.onclick=()=>{contactPage--;results()};pager.append(prev,el('span','',(es?'Página ':'Page ')+contactPage+' / '+total));const next=el('button','',es?'Siguiente':'Next');next.disabled=contactPage===total;next.onclick=()=>{contactPage++;results()};pager.append(next);content.append(pager)}results();box.append(el('p','contact-source',es?'La información de contacto puede cambiar. Verifica el directorio oficial antes de publicar.':'Staff assignments and contact details may change. Verify against the live directory before publishing.'));box.append(contactLink(es?'Ver el directorio oficial ↗':'View official staff directory ↗','https://santafenm.gov/human-resources/director-directory','contact-action secondary'))}
