function buildOpportunityDemoForm(p){
 const es=lang==='es';const form=oppEl('form','opp-form');form.noValidate=false;
 const title=oppEl('h2','',es?'Formulario de solicitud (demostración)':'Application form (demonstration)');
 const desc=oppEl('p','',es?'Complete los campos para explorar el proceso. Este formulario no envía ni guarda información.':'Explore the application process using the fields below. This form does not send or save information.');
 const warning=oppEl('div','opp-disclaimer',es?'SOLO DEMOSTRACIÓN: No incluya datos personales reales ni documentos confidenciales. No se aceptan solicitudes aquí.':'DEMO ONLY: Do not enter real personal information or confidential documents. Applications are not accepted here.');
 form.append(title,desc,warning);
 const grid=oppEl('div','opp-form-grid');
 const field=(label,type,required=true,wide=false,options=null)=>{
   const wrap=oppEl('label','opp-field'+(wide?' full':''));wrap.append(oppEl('span','',label+(required?' *':'')));
   const control=oppEl(type==='textarea'?'textarea':type==='select'?'select':'input');
   if(type!=='textarea'&&type!=='select')control.type=type;
   control.required=required;control.name='demo_'+label.replace(/[^a-z]/gi,'_').toLowerCase();
   if(type==='select'){const first=oppEl('option','',es?'Seleccione una opción':'Choose an option');first.value='';control.append(first);(options||[]).forEach(t=>{const o=oppEl('option','',t);o.value=t;control.append(o)})}
   if(type==='file'){control.accept='.pdf,.doc,.docx,.txt';wrap.classList.add('opp-form-file');wrap.append(oppEl('small','',es?'Opcional. El archivo permanece en su dispositivo.':'Optional. The file stays on your device.'))}
   wrap.append(control);grid.append(wrap);return control;
 };
 field(es?'Nombre completo':'Full name','text');
 field(es?'Correo electrónico':'Email address','email');
 field(es?'Teléfono':'Phone number','tel',false);
 field(es?'Organización o empresa':'Organization or business','text',false);
 if(p.type==='Grant'){
   field(es?'Nombre del proyecto':'Project name','text',true,true);
   field(es?'Monto solicitado (USD)':'Amount requested (USD)','number',true);
   field(es?'Categoría de subvención':'Grant category','select',true,false,es?['Comunidad','Arte','Medio ambiente','Otro']:['Community','Arts','Environment','Other']);
   field(es?'Cómo beneficiaría a Santa Fe':'How would this benefit Santa Fe?','textarea',true,true);
 }else if(p.type==='RFP'||p.type==='Bid'){
   field(es?'Nombre de la propuesta':'Proposal title','text',true,true);
   field(es?'Tipo de solicitante':'Applicant type','select',true,false,es?['Empresa','Organización sin fines de lucro','Persona']:['Business','Nonprofit','Individual']);
   field(es?'Resumen de la propuesta':'Proposal summary','textarea',true,true);
   field(es?'Presupuesto propuesto (USD)':'Proposed budget (USD)','number',false);
 }else{
   field(es?'Tipo de solicitud':'Application category','select',true,false,es?['Individual','Organización','Otro']:['Individual','Organization','Other']);
   field(es?'Descripción de la solicitud':'Application description','textarea',true,true);
 }
 field(es?'Documentos de respaldo':'Supporting documents','file',false,true);
 form.append(grid);
 const confirm=oppEl('label','opp-checkbox');const check=oppEl('input');check.type='checkbox';check.required=true;confirm.append(check,oppEl('span','',es?'Entiendo que esto es una demostración y que no se enviará ninguna solicitud.':'I understand this is a demonstration and no application will be submitted.'));form.append(confirm);
 const actions=oppEl('div','opp-form-actions');const submit=oppEl('button','opp-submit',es?'Probar envío':'Preview submission');submit.type='submit';const reset=oppEl('button','opp-reset',es?'Borrar formulario':'Clear form');reset.type='reset';actions.append(submit,reset);form.append(actions);
 const result=oppEl('div','opp-form-result');result.hidden=true;result.setAttribute('role','status');result.setAttribute('aria-live','polite');form.append(result);
 form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;result.hidden=false;result.textContent=es?'Vista previa completada para '+p.id+'. No se envió ni guardó información. Para solicitudes reales, use el portal oficial de la Ciudad.':'Demo preview completed for '+p.id+'. No information was submitted or saved. For real applications, use the City’s official application or procurement portal.';result.scrollIntoView({behavior:'smooth',block:'nearest'})});
 form.addEventListener('reset',()=>{result.hidden=true;result.textContent='' });
 return form;
}

