 const wrap=el('div','project-table-wrap');const table=el('table','project-table');const head=el('thead');const hr=el('tr');(es?['Reunión','Tipo','Tema','Departamento','Detalles']:['Meeting','Type','Topic','Department / office','Details']).forEach(t=>{const th=el('th','',t);th.scope='col';hr.append(th)});head.append(hr);table.append(head);const body=el('tbody');matches.slice((meetingPage-1)*10,meetingPage*10).forEach(m=>{const row=el('tr');m.forEach(t=>row.append(el('td','',t)));const td=el('td');const btn=el('button','project-open',es?'Ver detalles →':'View details →');btn.type='button';btn.onclick=()=>{board.querySelector('.meeting-detail-panel')?.remove();const detail=el('section','meeting-detail-panel');const back=el('button','back',es?'← Volver al directorio':'← Back to directory');back.onclick=()=>{detail.remove();board.querySelector('.project-tools').scrollIntoView({block:'start',behavior:'smooth'})};detail.append(back,el('h3','',m[0]),el('p','',es?'Tipo: '+m[1]+' · Tema: '+m[2]+' · Oficina: '+m[3]:'Type: '+m[1]+' · Topic: '+m[2]+' · Office: '+m[3]),el('p','',es?'Las fechas, los lugares, las agendas y las instrucciones para comentarios públicos deben confirmarse en el calendario oficial.':'Meeting dates, locations, agendas, and public comment instructions must be confirmed on the official calendar.'));const a=el('a','meeting-official-link',es?'Consultar calendario y agendas ↗':'Check calendar and agendas ↗');a.href=source.href;a.target='_blank';a.rel='noopener noreferrer';detail.append(a);board.append(detail);detail.scrollIntoView({block:'start',behavior:'smooth'})};td.append(btn);row.append(td);body.append(row)});table.append(body);wrap.append(table);results.append(wrap);
